output_text:
[
  {
    "id": "no_cart_single_file_aisles",
    "text": "Shopping carts are prohibited in single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "singleFileShelfAisle",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "no_push_cart_into_single_file",
    "text": "Agents must not push a cart from an open aisle into a single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "pushCartIntoSingleFileAisle": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE",
              {
                "not": "singleFileShelfAisle"
              }
            ]
          },
          "post": {
            "and": [
              "hasCart",
              "singleFileShelfAisle"
            ]
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "pushCartIntoSingleFileAisle"
    }
  },
  {
    "id": "retrieve_cart_after_parking",
    "text": "If an agent parks a cart at the mouth of a single-file aisle, they are obliged to retrieve it before leaving.",
    "abstraction": {
      "state_properties": {
        "singleFileAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "parkCartAtAisleMouth": {
          "pre": {
            "and": [
              "singleFileAisleMouth",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "retrieveCartAtAisleMouth": {
          "pre": {
            "and": [
              "singleFileAisleMouth",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkCartAtAisleMouth",
      "discharge": "retrieveCartAtAisleMouth"
    }
  },
  {
    "id": "dont_leave_parked_cart_behind",
    "text": "After returning to the mouth of a single-file aisle without the cart, the agent must not walk away into the open store before retrieving the cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "singleFileAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "walkAwayFromParkedCart": {
          "pre": {
            "and": [
              "singleFileAisleMouth",
              {
                "not": "hasCart"
              },
              "MOVE"
            ]
          },
          "post": {
            "and": [
              {
                "not": "singleFileShelfAisle"
              },
              {
                "not": "hasCart"
              }
            ]
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "walkAwayFromParkedCart"
    }
  },
  {
    "id": "cart_required_for_regular_shelf_interaction",
    "text": "Shelf interactions outside single-file aisles must be performed while holding the cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "regularShelfZone": {
          "and": [
            "adjShelf",
            {
              "not": "singleFileShelfAisle"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "regularShelfZone",
          "INTERACT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "cart_required_in_side_service_bays",
    "text": "In narrow side-service bays of width two, agents may not interact with shelves unless they have their cart.",
    "abstraction": {
      "state_properties": {
        "sideServiceBay": {
          "and": [
            "adjShelf",
            {
              "eq": [
                "freeWidthH",
                2
              ]
            },
            {
              "or": [
                "shelfE",
                "shelfW"
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "sideServiceBay",
          "INTERACT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "retrieve_after_on_foot_single_file_pick",
    "text": "After picking an item on foot inside a single-file aisle, the agent is obliged to return to the aisle mouth and retrieve the cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "singleFileAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "onFootShelfPickInSingleFileAisle": {
          "pre": {
            "and": [
              "singleFileShelfAisle",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "retrieveCartAtAisleMouth": {
          "pre": {
            "and": [
              "singleFileAisleMouth",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "onFootShelfPickInSingleFileAisle",
      "discharge": "retrieveCartAtAisleMouth"
    }
  },
  {
    "id": "park_only_at_wide_aisle_mouths",
    "text": "Agents may only park or drop carts at designated wide mouths of single-file aisles.",
    "abstraction": {
      "state_properties": {
        "singleFileAisleMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "designatedCartParkingSpot": {
          "and": [
            "singleFileAisleMouth",
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "dropCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "dropCart",
          {
            "not": "designatedCartParkingSpot"
          }
        ]
      }
    }
  }
]
